-- =====================================================================
-- 024 · Portafolio de servicios (tarjetas del inicio y página de servicios)
--  - Nueva plantilla de página "servicios": tarjetas agrupadas por categoría
--  - 12 servicios del Portafolio de servicios del portal anterior (PDF)
--  - Los marcados como "Destacar en portada" se muestran en el inicio
-- No borra ni cambia servicios que ya existan (se busca por slug).
-- =====================================================================
SET NAMES utf8mb4;
SET time_zone = '+00:00';

ALTER TABLE cms_paginas MODIFY plantilla ENUM('contenido','listado','documentos','galeria','enlace','calendario','historia','servicios') NOT NULL DEFAULT 'contenido';
UPDATE cms_paginas SET plantilla = 'servicios', descripcion = COALESCE(NULLIF(descripcion, ''), 'Conozca los servicios de salud que presta la E.S.E. Hospital San José del Guaviare, hospital de II nivel de complejidad y centro de referencia del departamento.')
  WHERE slug = 'portafolio-de-servicios' AND plantilla IN ('listado', 'contenido');

