INSERT INTO cms_entradas (pagina_id, titulo, slug, resumen, contenido, tipo, categoria, estado, destacada, autor, fecha_publicacion, imagen_destacada_id, orden, migrado_de)
SELECT p.id, 'Consulta externa', 'consulta-externa', 'Atención médica especializada oportuna, diligente y humanizada, con especialistas presenciales y por telemedicina.', '<p>En el servicio de Consulta Externa de la E.S.E. Hospital San José del Guaviare brindamos atención médica especializada oportuna, diligente y humanizada a nuestros usuarios, mediante un grupo multidisciplinario de especialistas idóneo, con amplia experiencia y con un profundo sentido humano.</p><p>Nuestro servicio está en constante evolución para adaptarse de la forma más adecuada a las necesidades de los pacientes, evaluando sus expectativas y buscando la mejor forma de responder a estas; por ello contamos con especialistas calificados y comprometidos con el manejo óptimo de las enfermedades.</p><h2>Horarios de atención</h2><ul><li><strong>Lunes a viernes:</strong> 7:00 a.m. a 12:00 p.m. y 2:00 p.m. a 6:00 p.m.</li><li><strong>Sábados:</strong> 8:00 a.m. a 1:00 p.m.</li></ul><h2>Especialidades básicas</h2><ul><li>Ginecoobstetricia</li><li>Anestesiología</li><li>Cirugía general</li><li>Medicina interna</li><li>Ortopedia y traumatología</li><li>Pediatría</li><li>Psicología y nutrición</li></ul><h2>Especialidades por jornada</h2><h3>Presencial</h3><ul><li>Dermatología</li><li>Endocrinología</li><li>Gastroenterología</li><li>Medicina física y rehabilitación</li><li>Neumología</li><li>Neurología</li><li>Oftalmología</li><li>Otorrinolaringología</li><li>Psiquiatría</li><li>Reumatología</li><li>Urología</li><li>Neurocirugía</li><li>Neurología pediátrica</li></ul><h3>Telemedicina</h3><ul><li>Alergología</li><li>Cardiología pediátrica</li><li>Cirugía plástica estética y reconstructiva</li><li>Cirugía vascular</li><li>Dermatología pediátrica</li><li>Dolor y cuidados paliativos</li><li>Endocrinología pediátrica</li><li>Gastroenterología pediátrica</li><li>Infectología</li><li>Nefrología pediátrica</li><li>Nefrología</li><li>Neumología pediátrica</li><li>Neurocirugía</li><li>Neurología pediátrica</li><li>Ortopedia y traumatología pediátrica</li><li>Psiquiatría pediátrica</li><li>Toxicología clínica</li><li>Urología pediátrica</li></ul><p><a href="https://esehospitalguaviare.gov.co/resourses/archivos/pdf/Portafolio-HOSPITAL-contorno-1-1%20(1).pdf#page=9" target="_blank" rel="noopener">Ver este servicio en el Portafolio de servicios (PDF)</a></p>', 'articulo', 'Consulta externa', 'publicada', 1, 'E.S.E. Hospital San José del Guaviare', NULL, (SELECT id FROM cms_multimedia WHERE url = 'https://esehospitalguaviare.gov.co/resourses/imgServicios/consulta.jpeg' LIMIT 1), 10, 'esehospitalguaviare.gov.co (Portafolio de servicios)'
  FROM cms_paginas p
 WHERE p.slug = 'portafolio-de-servicios'
   AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'consulta-externa');

INSERT INTO cms_entradas (pagina_id, titulo, slug, resumen, contenido, tipo, categoria, estado, destacada, autor, fecha_publicacion, imagen_destacada_id, orden, migrado_de)
SELECT p.id, 'Urgencias', 'urgencias', 'Atención de baja y mediana complejidad las 24 horas, con laboratorio, imágenes, farmacia y ambulancia permanentes.', '<p>Nuestra Unidad de atención médica de baja y mediana complejidad de Urgencias está dotada de los equipos biomédicos necesarios para brindar atención oportuna e integral a pacientes con afecciones agudas, contribuyendo al mejoramiento de su salud y, en caso de mayor complejidad, a mantener las condiciones vitales estables.</p><p><strong>Línea de emergencias (24 horas):</strong> <a href="tel:+573167440324">316 744 0324</a></p><h2>Servicios del área de Urgencias</h2><ul><li>Atención médica de urgencia.</li><li>Estabilización de pacientes agudos.</li><li>Observación.</li><li>Laboratorio clínico de urgencias 24 horas.</li><li>Valoración por especialidades las 24 horas: cirugía general, pediatría, medicina interna, anestesia, ortopedia, ginecología y traumatología.</li><li>Pequeñas cirugías y suturas.</li><li>Imagenología de urgencias 24 horas.</li><li>Remisiones de pacientes con patologías de alto nivel de complejidad.</li><li>Farmacia las 24 horas.</li><li>Terapia respiratoria.</li><li>Servicio de ambulancia urbana las 24 horas.</li><li>Servicios de curaciones e inyectología.</li></ul><p><a href="https://esehospitalguaviare.gov.co/resourses/archivos/pdf/Portafolio-HOSPITAL-contorno-1-1%20(1).pdf#page=22" target="_blank" rel="noopener">Ver este servicio en el Portafolio de servicios (PDF)</a></p>', 'articulo', 'Urgencias', 'publicada', 1, 'E.S.E. Hospital San José del Guaviare', NULL, (SELECT id FROM cms_multimedia WHERE url = 'https://esehospitalguaviare.gov.co/resourses/imgServicios/urgencias.jpg' LIMIT 1), 20, 'esehospitalguaviare.gov.co (Portafolio de servicios)'
  FROM cms_paginas p
 WHERE p.slug = 'portafolio-de-servicios'
   AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'urgencias');

INSERT INTO cms_entradas (pagina_id, titulo, slug, resumen, contenido, tipo, categoria, estado, destacada, autor, fecha_publicacion, imagen_destacada_id, orden, migrado_de)
SELECT p.id, 'Hospitalización', 'hospitalizacion', 'Atención humanizada, de calidad y segura para el paciente hospitalizado, desde su ingreso hasta su egreso.', '<p>Contamos con un equipo interdisciplinario que articula las actividades asistenciales, administrativas y de apoyo para mantener y mejorar cada día la atención humanizada, de calidad y seguridad del paciente hospitalizado desde su ingreso hasta su egreso.</p><p>La atención en esta unidad la orientamos hacia un servicio integral, teniendo en cuenta que su problema de salud no puede ser atendido de manera ambulatoria y requiere permanecer en la institución por más de un día.</p><p><a href="https://esehospitalguaviare.gov.co/resourses/archivos/pdf/Portafolio-HOSPITAL-contorno-1-1%20(1).pdf#page=14" target="_blank" rel="noopener">Ver este servicio en el Portafolio de servicios (PDF)</a></p>', 'articulo', 'Internación', 'publicada', 1, 'E.S.E. Hospital San José del Guaviare', NULL, (SELECT id FROM cms_multimedia WHERE url = 'https://esehospitalguaviare.gov.co/resourses/imgServicios/hospitalizados.jpeg' LIMIT 1), 30, 'esehospitalguaviare.gov.co (Portafolio de servicios)'
  FROM cms_paginas p
 WHERE p.slug = 'portafolio-de-servicios'
   AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'hospitalizacion');

INSERT INTO cms_entradas (pagina_id, titulo, slug, resumen, contenido, tipo, categoria, estado, destacada, autor, fecha_publicacion, imagen_destacada_id, orden, migrado_de)
SELECT p.id, 'Cirugía', 'cirugia', 'Dos salas de cirugía con equipos de alta tecnología y un equipo de profesionales con calidad humana.', '<p>En esta unidad tenemos a su servicio dos salas de cirugía dotadas con equipos biomédicos de alta tecnología y un equipo de profesionales con calidad humana.</p><p>Comprometidos con la salud del departamento, brindamos atención y tratamiento con un enfoque multidisciplinario, coordinado con profesionales pertenecientes a otras especialidades.</p><h2>Servicios</h2><ul><li>Cirugía general</li><li>Cirugía ortopédica</li><li>Cirugía ginecológica</li><li>Cirugía urológica</li><li>Cirugía maxilofacial reconstructiva</li><li>Cirugía otorrinolaringológica</li><li>Cirugía gastroenterológica</li></ul><p><a href="https://esehospitalguaviare.gov.co/resourses/archivos/pdf/Portafolio-HOSPITAL-contorno-1-1%20(1).pdf#page=20" target="_blank" rel="noopener">Ver este servicio en el Portafolio de servicios (PDF)</a></p>', 'articulo', 'Cirugía', 'publicada', 1, 'E.S.E. Hospital San José del Guaviare', NULL, (SELECT id FROM cms_multimedia WHERE url = 'https://esehospitalguaviare.gov.co/resourses/imgServicios/cirugia.jpeg' LIMIT 1), 40, 'esehospitalguaviare.gov.co (Portafolio de servicios)'
  FROM cms_paginas p
 WHERE p.slug = 'portafolio-de-servicios'
   AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'cirugia');

INSERT INTO cms_entradas (pagina_id, titulo, slug, resumen, contenido, tipo, categoria, estado, destacada, autor, fecha_publicacion, imagen_destacada_id, orden, migrado_de)
SELECT p.id, 'Atención del parto', 'atencion-del-parto', 'Unidad Materno Infantil con ginecólogos y ecografía obstétrica las 24 horas y valoración del recién nacido por pediatría.', '<p>Porque estamos comprometidos con el futuro de la región, valoramos el nacimiento como el acto más hermoso de la naturaleza, ofreciendo un servicio integral, con todas las especialidades médicas y quirúrgicas para la atención y el cuidado materno-infantil en nuestro nivel de complejidad.</p><h2>Tenga en cuenta</h2><p>En esta área tenemos disponibles tres ingresos: uno para la atención de maternas (consultas y urgencias), otro para sus acompañantes (cuando aplique) y uno para la recepción y salida de pacientes en remisión.</p><p>Contamos con una amplia sala de espera; recepción para información al familiar y de pertenencias; consultorio médico para consulta y urgencias ginecoobstétricas; sala de observación para estancias no superiores a 24 horas; sala de trabajo de parto con capacidad de 4 camas, con vigilancia constante; sala de parto dotada según la normatividad vigente; espacio para la adaptación neonatal; área para el cuidado de las maternas en el puerperio inmediato y mediato, con capacidad de 7 camas; un quirófano para urgencias obstétricas y un área para la atención de los neonatos en el servicio de Pediatría, además de áreas de enfermería, insumos y toma de monitorías ambulatorias.</p><h2>No queremos que corra riesgos, por eso contamos con</h2><ul><li>Atención de consulta desde el inicio de la gestación por ginecólogo-obstetra.</li><li>Ginecólogos con especialización en ecografía fetal avanzada y ecografía de II nivel obstétrica y ginecológica, disponibles las 24 horas del día.</li><li>Valoración del recién nacido por médico especialista en Pediatría.</li></ul><p><a href="https://esehospitalguaviare.gov.co/resourses/archivos/pdf/Portafolio-HOSPITAL-contorno-1-1%20(1).pdf#page=15" target="_blank" rel="noopener">Ver este servicio en el Portafolio de servicios (PDF)</a></p>', 'articulo', 'Internación', 'publicada', 1, 'E.S.E. Hospital San José del Guaviare', NULL, NULL, 50, 'esehospitalguaviare.gov.co (Portafolio de servicios)'
  FROM cms_paginas p
 WHERE p.slug = 'portafolio-de-servicios'
   AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'atencion-del-parto');

INSERT INTO cms_entradas (pagina_id, titulo, slug, resumen, contenido, tipo, categoria, estado, destacada, autor, fecha_publicacion, imagen_destacada_id, orden, migrado_de)
SELECT p.id, 'Unidad de Cuidados Intermedios (UCIM)', 'unidad-de-cuidados-intermedios', 'Tratamiento y monitoreo permanente con estándares de calidad para pacientes que requieren mayor complejidad.', '<p><strong>Tratamiento y monitoreo permanente con estándares de calidad.</strong></p><p>En la E.S.E. Hospital San José del Guaviare ponemos a disposición recurso humano entrenado y apoyo tecnológico con equipos biomédicos para prestar un excelente servicio de mayor complejidad.</p><p>Esta unidad cuenta con una completa infraestructura tecnológica, tanto de las demás unidades de servicio como de todas las especialidades médicas, dando solución a los problemas de salud de los pacientes que ameriten cuidado crítico.</p><p><a href="https://esehospitalguaviare.gov.co/resourses/archivos/pdf/Portafolio-HOSPITAL-contorno-1-1%20(1).pdf#page=16" target="_blank" rel="noopener">Ver este servicio en el Portafolio de servicios (PDF)</a></p>', 'articulo', 'Internación', 'publicada', 0, 'E.S.E. Hospital San José del Guaviare', NULL, NULL, 60, 'esehospitalguaviare.gov.co (Portafolio de servicios)'
  FROM cms_paginas p
 WHERE p.slug = 'portafolio-de-servicios'
   AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'unidad-de-cuidados-intermedios');

INSERT INTO cms_entradas (pagina_id, titulo, slug, resumen, contenido, tipo, categoria, estado, destacada, autor, fecha_publicacion, imagen_destacada_id, orden, migrado_de)
SELECT p.id, 'Etnopabellón', 'etnopabellon', 'Atención diferencial para las comunidades indígenas, con espacios acordes a sus tradiciones y medicina tradicional.', '<p>La E.S.E. Hospital San José del Guaviare cuenta con las instalaciones físicas y el diseño para la atención diferencial, de acuerdo con las tradiciones de las comunidades indígenas de nuestra región. Tiene capacidad de diez camas de hospitalización: cinco para atención pediátrica, tres para pacientes adultos y dos para pacientes aislados.</p><p>Teniendo en cuenta las costumbres indígenas, se dispone de un área de hamacas para los acompañantes y amplias áreas libres internas y externas para que los usuarios interactúen y realicen sus actividades tradicionales en un ambiente natural, enriquecido de vegetación y circulación de aire fresco. También se cuenta con un espacio exclusivo para la atención del payé, brindando así la posibilidad de servicios de medicina tradicional reconocida por nuestras comunidades indígenas.</p><p>En el Etnopabellón brindamos atención integral a los indígenas provenientes del sur del Meta, Vichada, Vaupés y Guaviare, con seguimiento y acompañamiento tanto del paciente como de sus acompañantes. Velamos por su atención médica, psicológica, alimentación, alojamiento y transporte, teniendo cuidado de no afectar sus costumbres y su cultura.</p><p><a href="https://esehospitalguaviare.gov.co/resourses/archivos/pdf/Portafolio-HOSPITAL-contorno-1-1%20(1).pdf#page=12" target="_blank" rel="noopener">Ver este servicio en el Portafolio de servicios (PDF)</a></p>', 'articulo', 'Internación', 'publicada', 0, 'E.S.E. Hospital San José del Guaviare', NULL, NULL, 70, 'esehospitalguaviare.gov.co (Portafolio de servicios)'
  FROM cms_paginas p
 WHERE p.slug = 'portafolio-de-servicios'
   AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'etnopabellon');

INSERT INTO cms_entradas (pagina_id, titulo, slug, resumen, contenido, tipo, categoria, estado, destacada, autor, fecha_publicacion, imagen_destacada_id, orden, migrado_de)
SELECT p.id, 'Laboratorio clínico', 'laboratorio-clinico', 'Disponible las 24 horas, con equipos automatizados y estrictos controles de calidad para resultados confiables.', '<p>Contamos con talento humano apto, calificado y con un alto grado de responsabilidad, con disponibilidad las 24 horas, conformado por bacteriólogos, auxiliares y equipos automatizados de alta calidad en cada una de las áreas funcionales, con estrictos controles de calidad que permiten entregar resultados confiables y con la rapidez necesaria para la atención oportuna de nuestros pacientes.</p><p><a href="https://esehospitalguaviare.gov.co/resourses/archivos/pdf/Portafolio-HOSPITAL-contorno-1-1%20(1).pdf#page=19" target="_blank" rel="noopener">Ver este servicio en el Portafolio de servicios (PDF)</a></p>', 'articulo', 'Apoyo diagnóstico y terapéutico', 'publicada', 1, 'E.S.E. Hospital San José del Guaviare', NULL, NULL, 80, 'esehospitalguaviare.gov.co (Portafolio de servicios)'
  FROM cms_paginas p
 WHERE p.slug = 'portafolio-de-servicios'
   AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'laboratorio-clinico');

INSERT INTO cms_entradas (pagina_id, titulo, slug, resumen, contenido, tipo, categoria, estado, destacada, autor, fecha_publicacion, imagen_destacada_id, orden, migrado_de)
SELECT p.id, 'Imágenes diagnósticas', 'imagenes-diagnosticas', 'Rayos X, ecografía y estudios de cuerpo entero con estándares de seguridad radiológica.', '<p>En la Unidad de Imágenes Diagnósticas realizamos estudios de cuerpo entero, corazón, hígado, páncreas, conductos biliares, pulmón y abdomen, en el menor tiempo posible gracias a la disponibilidad del equipo humano. Igualmente realizamos rayos X de extremidades, pelvis, cráneo, cara, cuello, columna vertebral, abdomen y genitourinario.</p><p>Además, cumplimos con estándares de seguridad radiológica, previniendo los riesgos físicos tanto para el paciente como para el profesional que realiza el procedimiento.</p><h2>Equipos de imagenología</h2><ul><li>Equipo de rayos X fijo</li><li>Equipo de rayos X portátil</li><li>Digitalizador</li><li>Sistema de captura digital CR Carestream de imagen (DYD)</li><li>Sistema de imagen de larga longitud para extremidades</li><li>Equipo de rayos X, arco en C</li><li>Ecógrafo</li></ul><p><a href="https://esehospitalguaviare.gov.co/resourses/archivos/pdf/Portafolio-HOSPITAL-contorno-1-1%20(1).pdf#page=18" target="_blank" rel="noopener">Ver este servicio en el Portafolio de servicios (PDF)</a></p>', 'articulo', 'Apoyo diagnóstico y terapéutico', 'publicada', 1, 'E.S.E. Hospital San José del Guaviare', NULL, NULL, 90, 'esehospitalguaviare.gov.co (Portafolio de servicios)'
  FROM cms_paginas p
 WHERE p.slug = 'portafolio-de-servicios'
   AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'imagenes-diagnosticas');

INSERT INTO cms_entradas (pagina_id, titulo, slug, resumen, contenido, tipo, categoria, estado, destacada, autor, fecha_publicacion, imagen_destacada_id, orden, migrado_de)
SELECT p.id, 'Terapia física y respiratoria', 'terapia-fisica-y-respiratoria', 'Tratamientos seguros y efectivos con técnicas y tecnología para mejorar la calidad de vida de niños y adultos.', '<h2>Terapia física</h2><p>Brindamos una atención integral y especializada con tratamientos seguros y efectivos, con los cuales contribuimos al mejoramiento de la calidad de vida de los guaviarenses. Nuestro personal cuenta con conocimiento y experiencia; además, brindamos una atención con calidez y profesionalismo, utilizando técnicas eficaces, seguras y tecnología avanzada.</p><h3>Técnicas</h3><ul><li>Hidroterapia</li><li>Termoterapia superficial y profunda</li><li>Crioterapia</li><li>Electroterapia</li><li>Vibroterapia</li><li>Laserterapia</li><li>Mecanoterapia</li><li>Gimnasia médica</li><li>Balonterapia</li><li>Terapia vestibular</li><li>Ayudas para la marcha y la verticalización</li><li>Tracción lumbar</li><li>Técnicas de neurorrehabilitación</li><li>Estimulación temprana</li><li>Curso psicoprofiláctico</li><li>Programa de adulto mayor</li></ul><h2>Terapia respiratoria</h2><p>Realizamos análisis de diagnóstico exhaustivo para determinar la causa, el estado actual y las posibles consecuencias de su patología, con un equipo médico y asistencial altamente especializado.</p><p><strong>Contamos con personal capacitado; atención dirigida a niños y adultos.</strong></p><p><a href="https://esehospitalguaviare.gov.co/resourses/archivos/pdf/Portafolio-HOSPITAL-contorno-1-1%20(1).pdf#page=10" target="_blank" rel="noopener">Ver este servicio en el Portafolio de servicios (PDF)</a></p>', 'articulo', 'Apoyo diagnóstico y terapéutico', 'publicada', 1, 'E.S.E. Hospital San José del Guaviare', NULL, NULL, 100, 'esehospitalguaviare.gov.co (Portafolio de servicios)'
  FROM cms_paginas p
 WHERE p.slug = 'portafolio-de-servicios'
   AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'terapia-fisica-y-respiratoria');

INSERT INTO cms_entradas (pagina_id, titulo, slug, resumen, contenido, tipo, categoria, estado, destacada, autor, fecha_publicacion, imagen_destacada_id, orden, migrado_de)
SELECT p.id, 'Trabajo social', 'trabajo-social', 'Acompañamiento integral al paciente y su familia, incluido el enlace indígena o atención étnica.', '<p>El área de Trabajo Social está enfocada en brindar un acompañamiento integral al paciente y su familia, a través del reconocimiento de los factores protectores y los recursos internos con los que cuenta para facilitar la resolución de conflictos, situaciones personales, familiares y sociales que afectan el proceso de atención. También busca incidir en la adherencia a los tratamientos ambulatorios propuestos por el equipo médico tratante.</p><h2>Enlace indígena o atención étnica</h2><p>Brindamos una atención integral a los indígenas provenientes del sur del Meta, Vichada, Vaupés y Guaviare, realizando seguimiento y acompañamiento tanto del paciente como de sus acompañantes, velando por una atención médica, psicológica, alimentación, alojamiento y transporte, teniendo cuidado de no afectar su cultura y sus costumbres.</p><p><a href="https://esehospitalguaviare.gov.co/resourses/archivos/pdf/Portafolio-HOSPITAL-contorno-1-1%20(1).pdf#page=23" target="_blank" rel="noopener">Ver este servicio en el Portafolio de servicios (PDF)</a></p>', 'articulo', 'Atención al usuario', 'publicada', 0, 'E.S.E. Hospital San José del Guaviare', NULL, NULL, 110, 'esehospitalguaviare.gov.co (Portafolio de servicios)'
  FROM cms_paginas p
 WHERE p.slug = 'portafolio-de-servicios'
   AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'trabajo-social');

INSERT INTO cms_entradas (pagina_id, titulo, slug, resumen, contenido, tipo, categoria, estado, destacada, autor, fecha_publicacion, imagen_destacada_id, orden, migrado_de)
SELECT p.id, 'Servicio de Información y Atención al Usuario (SIAU)', 'servicio-de-informacion-y-atencion-al-usuario', 'Agentes que orientan a usuarios y pacientes para acceder con calidad y oportunidad a los servicios.', '<p>El Servicio de Información y Atención al Usuario está conformado por los agentes SIAU, quienes tienen como función orientar al usuario o paciente en los diferentes servicios de la IPS, para que pueda acceder con calidad y oportunidad al servicio requerido. Todo ello con calidad humana y respeto, de forma que el usuario se sienta acompañado y note el interés del hospital por su satisfacción.</p><p>Para peticiones, quejas, reclamos, sugerencias, felicitaciones o denuncias puede usar el formulario de <a href="/pqrsf">PQRSFD</a>.</p><p><a href="https://esehospitalguaviare.gov.co/resourses/archivos/pdf/Portafolio-HOSPITAL-contorno-1-1%20(1).pdf#page=23" target="_blank" rel="noopener">Ver este servicio en el Portafolio de servicios (PDF)</a></p>', 'articulo', 'Atención al usuario', 'publicada', 0, 'E.S.E. Hospital San José del Guaviare', NULL, NULL, 120, 'esehospitalguaviare.gov.co (Portafolio de servicios)'
  FROM cms_paginas p
 WHERE p.slug = 'portafolio-de-servicios'
   AND NOT EXISTS (SELECT 1 FROM cms_entradas e WHERE e.pagina_id = p.id AND e.slug = 'servicio-de-informacion-y-atencion-al-usuario');
